        logger.info(f"{server}: passed")
    except ConnectionError as exc:
        logger.error(f"{server}: {exc}")
    except Exception as exc:
        logger.error(f"{server}: unexpected ({exc})")

class HealthCheckError(Exception):
    pass

def check_server(server, max_attempts=3):
    for attempt in range(1, max_attempts + 1):
        try:
            return connect_and_check(server)
        except ConnectionError:
            logger.warning(f"attempt {attempt} failed")
    raise HealthCheckError(server)
